// Extract tool call arguments from Vapi payload
const body = $input.item.json.body || $input.item.json;
const toolCalls = body.message?.toolCalls || [];

let args = {};
let callId = 'call_test_id';

if (toolCalls.length > 0) {
  callId = toolCalls[0].id;
  args = toolCalls[0].function?.arguments || {};
  if (typeof args === 'string') {
    args = JSON.parse(args);
  }
} else {
  args = body;
}

// Compute 30-minute booking duration
const startTime = new Date(args.appointment_time || new Date());
const endTime = new Date(startTime.getTime() + 30 * 60000);

return {
  call_id: callId,
  patient_name: args.patient_name || 'Patient',
  phone: args.phone || 'Not Provided',
  reason: args.reason || 'General Checkup',
  start_time: startTime.toISOString(),
  end_time: endTime.toISOString()
};

